// Ovonic O-35C-2200-4S1P-XT60 shrink-wrapped pack. Origin: bottom-face centre, Z up.
// Envelope 77 x 34 x 34 mm (Ovonic spec list). Long edges (along X) rounded; radius not
// published -> conservative 3 mm. Lead end (+X) kept flat: tab fold/lead exits not dimensioned.
const L = 77, W = 34, H = 34, r = 3;
// YZ cross-section (rounded square) extruded along +X
const body = drawRoundedRectangle(W, H, r)
  .sketchOnPlane('YZ', -L / 2)
  .extrude(L)
  .translate([0, 0, H / 2]);
return body;
